// Общий код для отчётов у менеджера (business testim, сессия bizt): кандидат по точному имени (list_candidates, как экран /candidates),
// ответ get_candidate_report (p_reason: null — так читает экран бизнеса) и ожидание шапки отчёта. Только чтение.
import { Page } from '@playwright/test';
import { expect } from '../../fixtures';
import { openWithApi, Api } from '../support/api';
import { listCandidates } from '../candidates/hiring-support';
import type { ContentFlag } from '../admin-support/support-helpers';

export type ReportView = {
  candidate?: { id: string; full_name: string };
  attempt?: { end_reason?: string | null; duration_seconds?: number | null; content_flags?: ContentFlag[] | null } | null;
  recording?: { duration_seconds?: number | null } | null;
  report?: { status?: string } | null;
};

export async function candidateByName(api: Api, name: string): Promise<string> {
  const found = (await listCandidates(api)).filter((c) => c.full_name === name);
  expect(found, `кандидат «${name}» не найден (или не уникален) в list_candidates (QA-данные testim)`).toHaveLength(1);
  return found[0].id;
}

export async function viewById(api: Api, id: string): Promise<ReportView> {
  const res = await api.rpc('get_candidate_report', { p_candidate_id: id, p_reason: null });
  expect(res.status(), `get_candidate_report: ${await res.text()}`).toBe(200);
  const body = await res.json();
  return (Array.isArray(body) ? body[0] : body) as ReportView;
}

/** Кандидат по имени: id, API-клиент и ответ get_candidate_report (источник истины для проверок экрана). */
export async function viewByName(page: Page, name: string) {
  const api = await openWithApi(page, '/candidates');
  const id = await candidateByName(api, name);
  return { api, id, view: await viewById(api, id) };
}

/** Открывает отчёт и ждёт шапку (она есть и у готового отчёта, и у отчёта в ошибке). */
export async function openReportPage(page: Page, id: string) {
  await page.goto(`/candidates/${id}/report`);
  const meta = page.getByTestId('report-meta');
  await expect(meta).toBeVisible({ timeout: 40_000 });
  return meta;
}
